-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- the seed copy inserts items for every seeded template of the org, not only the ones it just inserted
-- targets: c17
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._seed_org_checklist_templates(p_org_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count integer;
BEGIN
  IF p_org_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id) THEN
    RETURN 0;
  END IF;

  WITH inserted AS (
    INSERT INTO public.checklist_templates
      (organization_id, name, description, sort_order, seed_key, seeded_at, created_by)
    SELECT p_org_id, s.name, s.description, s.sort_order, s.seed_key, now(), NULL
      FROM public.checklist_seed_templates s
    ON CONFLICT (organization_id, seed_key) WHERE seed_key IS NOT NULL DO NOTHING
    RETURNING id, seed_key
  ), inserted_items AS (
    INSERT INTO public.checklist_template_items
      (template_id, title, description, is_required, expected_document_type, sort_order)
    SELECT i.id,
           e.elem ->> 'title',
           e.elem ->> 'description',
           COALESCE((e.elem ->> 'is_required')::boolean, false),
           e.elem ->> 'expected_document_type',
           (e.ord * 10)::integer
      FROM (SELECT t.id, t.seed_key FROM public.checklist_templates t
             WHERE t.organization_id = p_org_id AND t.seed_key IS NOT NULL) i
      JOIN public.checklist_seed_templates s ON s.seed_key = i.seed_key
      CROSS JOIN LATERAL jsonb_array_elements(s.items) WITH ORDINALITY AS e(elem, ord)
    RETURNING 1
  )
  SELECT count(*)::integer INTO v_count FROM inserted;

  RETURN v_count;
END
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public._seed_org_checklist_templates(uuid)'::regprocedure) LIKE '%t.organization_id = p_org_id AND t.seed_key IS NOT NULL%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('items for every seeded template') AS mutation;
